pub use check::{RESERVED_COMMANDS, RESERVED_FLAGS};
pub use host::Host;
pub use spec::{CliFlag, CliMacro, CliOp, CliRemediation, CliSpec, FlagKind};

use std::process::ExitCode;

use tungsten_runtime::{ClientOptions, ConfigError, Dispatch};

/// Run the CLI: parse `argv` (including the program name), build the client
/// with `make_client` from the options the flags, environment and config
/// file give, run the command and print its output. Returns the exit code
/// of the output contract.
///
/// `make_client` is called once to learn which credentials the API takes
/// and once more with them, so it must be cheap and repeatable.
pub async fn run<D, F>(spec: &CliSpec, argv: Vec<String>, make_client: F) -> ExitCode
where
    D: Dispatch,
    F: Fn(ClientOptions) -> Result<D, ConfigError>,
{
    ExitCode::from(run_with(spec, argv, Host::process(), make_client).await)
}

/// [`run`] on another [`Host`]: the environment and streams are the host's.
/// Returns the exit code.
pub async fn run_with<D, F>(spec: &CliSpec, argv: Vec<String>, host: Host, make_client: F) -> u8
where
    D: Dispatch,
    F: Fn(ClientOptions) -> Result<D, ConfigError>,
{
    let json = argv.iter().any(|a| a == "--json");
    let no_color = argv.iter().any(|a| a == "--no-color");
    let mut ctx = ctx::Ctx::new(spec, host, json, no_color);
    let code = exec::drive(&mut ctx, argv, &make_client).await;
    ctx.finish();
    code
}
